import AppKit

/// Иконки соцсетей/мессенджеров для подменю «Поделиться». Монохромные (template) —
/// система тинтует их под цвет меню (свет/тёмная тема). Источник: simple-icons (CC0),
/// растеризованы 36px и вшиты base64 — без бандлинга ресурсов (надёжно и self-contained).
enum ShareIcons {
    private static let data: [String: String] = [
        "telegram": "",
        "vk": "",
        "x": "",
        "whatsapp": "",
        "facebook": "",
        "reddit": "",
    ]

    /// Template-иконка сети размером 16pt, или nil.
    static func image(_ name: String) -> NSImage? {
        guard let b64 = data[name], let d = Data(base64Encoded: b64),
              let img = NSImage(data: d) else { return nil }
        img.size = NSSize(width: 16, height: 16)
        img.isTemplate = true
        return img
    }
}
